// Meldet neue Pull Requests (geöffnet, wieder geöffnet, aus Draft freigegeben) nach Telegram.
// Alles andere (ping, synchronize, closed, Drafts) wird still verworfen.
const SKIP_RENOVATE = false;   // true: Renovate-PRs nicht melden (die stehen auch im Tagesbericht)
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const out = [];
for (const item of $input.all()) {
  const p = item.json.body ?? item.json;          // GitHub Trigger liefert {body, headers, query}
  const pr = p.pull_request;
  if (!pr || !['opened', 'reopened', 'ready_for_review'].includes(p.action) || pr.draft) continue;
  const bot = pr.user?.type === 'Bot';
  if (bot && SKIP_RENOVATE && /renovate/i.test(pr.user.login)) continue;
  const head = { opened: '🆕 Neuer PR', reopened: '♻️ PR wieder geöffnet', ready_for_review: '👀 PR bereit zum Review' }[p.action];
  const labels = (pr.labels || []).map(l => l.name);
  const lines = [
    '<b>' + head + '</b> in ' + esc(p.repository?.full_name),
    '<a href="' + pr.html_url + '">#' + pr.number + ' ' + esc(pr.title) + '</a>',
    (bot ? '🤖 ' : '👤 ') + esc(pr.user?.login) + ' · ' + esc(pr.head?.ref) + ' → ' + esc(pr.base?.ref),
    '+' + (pr.additions ?? '?') + ' / −' + (pr.deletions ?? '?') + ' Zeilen in ' + (pr.changed_files ?? '?') + ' Dateien',
  ];
  if (labels.length) lines.push('🏷 ' + labels.map(esc).join(', '));
  out.push({ json: { text: lines.join('\n') } });
}
return out;
